-- loads_03_delivered.sql
-- The freight behind the settlements: one load per paid trip.
--
-- Generated from the settlement route lines, so every one of them has a load to
-- point at. Before this, dbo.Loads and dbo.SettlementRoutes were unrelated --
-- the board advertised freight nobody was paid for, and drivers were paid for
-- trips that never existed as loads.
--
-- The rate here is the CARRIER's revenue, not the driver's pay. A load paying
-- the driver $0.62/mi bills the customer around $2.90/mi; equal figures would
-- be the tell that the data is invented.
--
-- Requires settlement_05_link.sql. Run before the settlement files, which
-- reference these ids.

SET NOCOUNT ON;

MERGE dbo.Loads AS target
