ON target.id = source.id
WHEN MATCHED THEN
    UPDATE SET
        origin         = source.origin,
        destination    = source.destination,
        miles          = source.miles,
        rate           = source.rate,
        equipment      = source.equipment,
        status         = source.status,
        driver_code    = source.driver_code,
        delivered_date = source.delivered_date
WHEN NOT MATCHED THEN
    INSERT (id, origin, destination, miles, rate, equipment, status, driver_code, delivered_date)
    VALUES (source.id, source.origin, source.destination, source.miles, source.rate,
            source.equipment, source.status, source.driver_code, source.delivered_date);
